import * as THREE from 'three';
import {createExerciseCycle} from './exercise-cycle.js';
import {createStairModel} from './stair-model.js';
import {createStairSession,fitStairCamera} from './stair-session.js';
export const STAIR_BODY=`<div class="gym-layout"><div class="gym-court" id="stair-court" role="img" aria-label="원래 도름이가 움직이는 계단에 번갈아 발을 딛는 모습" tabindex="0"></div><section class="gym-panel" id="stair-panel"><p id="stair-status" role="status"></p><label>걷는 방법 <select id="stair-mode"><option value="easy">편하게 운동 · 자동 계단 걷기</option><option value="hold">길게 누르면 이어 걷기</option><option value="manual">왼발 · 오른발 직접 고르기</option></select></label><label class="gym-repeat" for="stair-repeat"><input id="stair-repeat" type="checkbox">5초 쉬었다가 반복</label><div class="gym-actions gym-exercise-actions"><button id="stair-start">계단 걷기 시작</button><button id="stair-pause">잠깐 멈추기</button><button id="stair-stop">운동 멈추기</button><button id="stair-exit">멈추고 내려오기</button></div><label>걸음 빠르기 <input id="stair-tempo" type="range" min="0.45" max="1" step="0.05" value="0.8"></label><label>연습 걸음 <select id="stair-goal"><option value="10">10걸음 · 1연습층</option><option value="20">20걸음 · 2연습층</option><option value="30">30걸음 · 3연습층</option></select></label><div class="gym-hold" id="stair-practice-controls"><button id="stair-left">왼발</button><button id="stair-right">오른발</button><button id="stair-hold">누르는 동안 걷기</button></div><p id="stair-score" role="status"></p><details id="stair-help"><summary>안내 보기</summary><p>편하게 운동은 시작을 누르면 자동으로 움직여요. 반복을 고르면 움직임을 마치고 두 발을 딛은 채 5초 쉬고 다시 운동해요. 반복은 처음에는 꺼져 있어요.</p><p>운동 멈추기는 다음 반복을 취소하고 안전하게 멈춰요. 잠깐 멈추기나 화면을 떠나기도 반복을 취소해요. 계속하기는 현재 운동만 이어가요.</p><p>계단에 발을 옮겨 체중을 실으면 한 걸음이에요. 10걸음은 1연습층으로 표시해요. 실제 올라간 높이도 함께 보여요. 빠르게 연달아 누를 필요 없어요.</p><p>직접 고르기는 ← 왼발 · → 오른발, 길게 누르기는 스페이스를 써요. 멈춘 뒤에도 언제든 다시 시작할 수 있어요. 나가면 움직임을 마친 뒤 멈춘 계단으로 내려와요.</p><p>안내를 접어도 자세는 그대로예요. 보상이나 연속 기록은 없어요.</p></details></section></div>`;
export function createStairController({ui,getView,getActors,stage,isAllowed=()=>true,onChange=()=>{},clearInput=()=>{},doc=globalThis.document,win=globalThis.window,sessionFactory=createStairSession,modelFactory=createStairModel,fitCamera=fitStairCamera}){
 const camera=new THREE.OrthographicCamera(),$=id=>doc.querySelector('#'+id);let live=null,pending=false,generation=0;
 function listen(node,type,fn,opts){if(!node)return;const token=generation,guarded=e=>{if(token===generation&&live)fn(e);};node.addEventListener(type,guarded,opts);live.listeners.push([node,type,guarded,opts]);}
 function clear(){clearInput();if(!live)return;live.pointers.clear();live.keys.clear();live.model.setInput({held:false});}
 function held(){if(live)live.model.setInput({held:live.pointers.size>0||live.keys.size>0});}
 function render(){if(!live)return;const s=live.model.snapshot(),p=live.session.phase,paused=live.suspended||s.paused,cycle=live.cycle.snapshot(),ready=live.session.ready&&['idle','ready','stopped'].includes(s.state);$('stair-status').textContent=paused?'멈췄어요. 계속하기는 현재 운동만 이어가요':p.startsWith('boarding')?'멈춘 계단으로 천천히 올라가요':p.startsWith('exiting')?'계단이 멈췄어요. 발을 번갈아 내려와요':live.exiting?'딛고 있던 걸음을 마친 뒤 내려와요':cycle.phase==='rest'?`두 발을 딛고 쉬어요 · ${Math.ceil(cycle.remaining)}초 뒤 자동으로 운동해요`:ready?'준비됐어요. 걷기 시작을 눌러요':`${s.expected==='left'?'왼발':'오른발'} 차례 · ${Math.round(s.tempo*60)}걸음/분`;$('stair-score').textContent=`${s.transfers} / ${s.goal}걸음 · ${s.floors}연습층 · 올라간 높이 ${s.climbed.toFixed(2)}m`;$('stair-start').disabled=!ready||paused||live.exiting||cycle.phase==='rest';$('stair-start').textContent=s.state==='stopped'?'한 번 더 걷기':'계단 걷기 시작';$('stair-pause').textContent=paused?'계속하기':'잠깐 멈추기';$('stair-exit').disabled=live.exiting;$('stair-stop').disabled=live.exiting||paused||(!cycle.enabled&&s.state!=='active');$('stair-repeat').checked=cycle.enabled;$('stair-repeat').disabled=live.exiting||paused||s.mode!=='easy';$('stair-score').hidden=s.mode==='easy';for(const id of['stair-mode','stair-tempo','stair-goal'])$(id).disabled=!ready||paused||live.exiting;for(const side of['left','right'])$('stair-'+side).disabled=s.mode!=='manual'||s.state!=='active'||paused||live.exiting;$('stair-practice-controls').hidden=s.mode==='easy';$('stair-hold').disabled=s.mode!=='hold'||s.state!=='active'||paused||live.exiting;}
 function clean({restore}={}){pending=false;generation++;if(!live)return;const old=live;live=null;old.observer?.disconnect();for(const[n,t,f,o]of old.listeners)n.removeEventListener(t,f,o);old.cycle.dispose();old.model.dispose?.();old.session.dispose({restore:restore??(getView()===old.source)});stage.classList.remove('gym-open');doc.body?.classList.remove('gym-open');clearInput();onChange();}
 function cancel(){const owned=!!live||pending;clean();if(owned)ui.close();}
 function close(){if(!live||live.exiting)return;clear();live.cycle.cancel();live.exiting=true;live.model.stop('exit');live.session.requestExit();render();}
 function pause(){if(!live)return;clear();live.cycle.cancel();live.suspended=true;live.model.pause();live.session.pause?.();render();}
 function open(){if(live||pending||!isAllowed())return false;const source=getView();if(!source?.schoolView?.gymView?.stairs)return false;if(source.residents?.stairOccupied?.()){source.residents.requestStairYield?.();ui.toast('거북이가 계단을 멈추고 내려올게요. 잠깐만 기다려 주세요');return false;}pending=true;const token=++generation;
 const accepted=ui.workshop('천국의 계단 · 한 걸음씩',STAIR_BODY,()=>{if(token!==generation||!pending)return;if(getView()!==source){pending=false;return;}pending=false;let session;try{session=sessionFactory({view:source,...getActors()});live={session,cycle:createExerciseCycle(),model:modelFactory({mode:'easy',tempo:.8,goal:10,travel:session.travel??0}),source,listeners:[],pointers:new Set(),keys:new Set(),suspended:false,exiting:false,fit:''};stage.classList.add('gym-open');doc.body?.classList.add('gym-open');clearInput();onChange();
  const act=(id,fn)=>listen($(id),'click',e=>{if(token!==generation||!live||$(id).disabled)return;if(e.detail>0&&live.cancelledPointer)return;e.preventDefault();fn();});
  act('stair-start',()=>{clear();if(live.session.ready){live.model.start();live.cycle.start();}render();});act('stair-stop',()=>{clear();live.cycle.cancel();live.model.stop('manual');render();});act('stair-exit',close);act('stair-pause',()=>{if(doc.hidden)return;if(live.suspended||live.model.snapshot().paused){clear();live.suspended=false;live.model.resume();render();}else pause();});
  listen($('stair-repeat'),'input',()=>{if($('stair-repeat').disabled)return;live.cycle.setEnabled($('stair-repeat').checked);if(live.cycle.snapshot().enabled&&live.model.snapshot().state==='active')live.cycle.start();render();});
  for(const id of['stair-mode','stair-tempo','stair-goal'])listen($(id),'input',()=>{if($(id).disabled)return;clear();if(id==='stair-mode')live.cycle.cancel();if(id==='stair-mode')live.model.setMode($(id).value);else if(id==='stair-tempo')live.model.setTempo(Number($(id).value));else live.model.setGoal(Number($(id).value));render();});
  for(const side of['left','right'])act('stair-'+side,()=>{live.model.setInput({step:side});render();});
  const button=$('stair-hold');listen(button,'pointerdown',e=>{if(button.disabled||e.button!==0||e.isPrimary===false)return;e.preventDefault();live.cancelledPointer=false;button.setPointerCapture?.(e.pointerId);live.pointers.add(e.pointerId);held();});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(button,type,e=>{if(!live)return;if(type!=='pointerup')live.cancelledPointer=true;live.pointers.delete(e.pointerId);held();});
  listen(doc,'keydown',e=>{if(!live||e.repeat||e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const control=e.target?.closest?.('button,a,summary,[role="button"]')??(['BUTTON','A','SUMMARY'].includes(e.target?.tagName)?e.target:null);if(control&&control!==button)return;const s=live.model.snapshot();if(live.suspended||s.paused||live.exiting||s.state!=='active')return;if(e.code==='Space'&&s.mode==='hold'){e.preventDefault();live.keys.add(e.code);held();}else if(s.mode==='manual'&&['ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();live.model.setInput({step:e.code==='ArrowLeft'?'left':'right'});render();}});listen(doc,'keyup',e=>{if(live){live.keys.delete(e.code);held();}});
  listen($('stair-panel'),'pointerdown',()=>{if(live)live.cancelledPointer=false;},true);listen($('stair-panel'),'pointercancel',()=>{if(live)live.cancelledPointer=true;},true);
  const modal=$('modal'),exit=modal?.querySelector?.('[data-close]');if(exit)exit.onclick=e=>{if(token!==generation||!live)return;e.preventDefault();close();};listen(modal,'cancel',e=>{e.preventDefault();close();});listen(modal,'click',e=>{if(e.target===modal){e.preventDefault();e.stopImmediatePropagation?.();}},true);
  listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});listen(win,'pagehide',cancel);const resize=()=>{if(live&&token===generation)viewport(stage.clientWidth,stage.clientHeight);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('stair-court'));}render();resize();$('stair-court').focus();return()=>{if(token===generation)clean();};
 }catch(error){if(live)clean();else session?.dispose();pending=false;ui.close();ui.toast('계단 뒤쪽에 빈자리가 필요해요. 잠깐 뒤 다시 해 주세요');}},{kind:'gym-workshop',closeLabel:'내려오기'});if(!accepted&&token===generation)pending=false;return accepted;}
 function runtimeFailure(){const restore=!!live&&getView()===live.source;clean({restore});ui.close();ui.toast('계단 걷기를 멈췄어요. 잠깐 뒤 다시 해 주세요');}
 function tick(dt){if(!live)return;if(getView()!==live.source){clean({restore:false});ui.close();return;}if(doc.hidden){if(!live.suspended)pause();return;}try{const s=live.model.snapshot();if(!live.suspended&&!s.paused){if(live.session.ready&&s.state==='idle')live.model.ready();live.model.update(dt);live.session.tick(dt,live.model.snapshot());if(live.cycle.update(dt,live.model.snapshot(),live.session.ready)&&!live.exiting)live.model.start();}if(live.session.done){clean();ui.close();return;}render();}catch(error){runtimeFailure();}}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=$('stair-court').getBoundingClientRect(),a=stage.getBoundingClientRect(),rect={x:Math.max(0,b.left-a.left),y:Math.max(0,b.top-a.top),width:Math.max(1,Math.min(b.width,width)),height:Math.max(1,Math.min(b.height,height))},key=Object.values(rect).join(',');if(key!==live.fit){try{fitCamera(camera,live.session.root,rect);live.fit=key;}catch(error){runtimeFailure();}}return rect;}
 return{open,close,cancel,pause,tick,viewport,camera,dispose:cancel,get active(){return!!live;},snapshot:()=>live?{...live.model.snapshot(),paused:live.suspended||live.model.snapshot().paused,cycle:live.cycle.snapshot(),session:live.session.snapshot(),exiting:live.exiting}:null};
}
